"""robots.txt parsing and matching implemented from scratch (RFC 9309-ish)."""


def _match_pattern(pattern, path):
    """Return length of matched prefix if pattern matches path, else None.

    Supports '*' wildcard and '$' end anchor. Returns the number of
    characters of `path` consumed by the match (used for longest-match).
    """
    anchored_end = pattern.endswith("$")
    if anchored_end:
        pattern = pattern[:-1]

    # Split pattern on '*' into literal segments.
    segments = pattern.split("*")

    matched = 0
    pos = 0

    for i, seg in enumerate(segments):
        if seg == "":
            continue
        if i == 0:
            # First segment must match at the start.
            if not path.startswith(seg):
                return None
            pos = len(seg)
            matched = len(seg)
        elif i == len(segments) - 1 and not anchored_end:
            # Last segment (no anchor): find it, then everything after is
            # consumed by the trailing wildcard, so the match succeeds.
            idx = path.find(seg, pos)
            if idx == -1:
                return None
            matched = idx + len(seg)
            pos = matched
        else:
            idx = path.find(seg, pos)
            if idx == -1:
                return None
            pos = idx + len(seg)
            matched = pos

    if anchored_end:
        last_seg = segments[-1]
        if not pattern:  # pattern was just "$"
            return 0 if path == "" else None
        if not path.startswith(last_seg, max(pos - len(last_seg), 0)) and pos != len(path):
            pass  # handled below via exact end check
        if pos != len(path):
            return None

    return matched


def _pattern_matches(pattern, path):
    """Boolean match honoring * wildcard and $ end anchor."""
    anchored = pattern.endswith("$")
    if anchored:
        pattern = pattern[:-1]
        if pattern == "":
            return path == ""
        if not path.endswith(pattern):
            return False
        pattern = "*" + pattern  # only need suffix to match
    parts = pattern.split("*")
    pos = 0
    for part in parts:
        if part == "":
            continue
        idx = path.find(part, pos)
        if idx == -1:
            return False
        pos = idx + len(part)
    return True


class RuleGroup:
    def __init__(self):
        self.agents = []  # lowercased user-agent tokens
        self.rules = []   # list of (allow: bool, pattern: str)

    def longest_agent_match(self, agent):
        """Length of the longest agent token that is a prefix of `agent`."""
        best = 0
        a = agent.lower()
        for token in self.agents:
            if a.startswith(token) and len(token) > best:
                best = len(token)
        return best

    def allow(self, path):
        """Decide fetchability of `path` for this group."""
        best_len = -1
        result = True  # no rules => allowed
        for is_allow, pattern in self.rules:
            if not _pattern_matches(pattern, path):
                continue
            # Longest matched pattern wins; Allow wins ties.
            key = len(pattern.rstrip("$")) if pattern != "$" else 1
            # Use effective pattern length; tie-break toward Allow.
            if key > best_len or (key == best_len and is_allow):
                best_len = key
                result = is_allow
        return result


class Robots:
    def __init__(self):
        self.groups = []

    def group_for(self, agent):
        agent_l = agent.lower()
        best_len = -1
        best = None
        for g in self.groups:
            m = g.longest_agent_match(agent_l)
            if m > best_len:
                best_len = m
                best = g
        # '*' fallback group has match length 1; anything shorter means no group
        if best is None or best_len < 1:
            # No matching group at all -> per spec, full access.
            return None
        return best

    def can_fetch(self, agent, path):
        g = self.group_for(agent)
        if g is None:
            return True
        return g.allow(path)


def parse(text):
    """Parse robots.txt text into a Robots object."""
    robots = Robots()
    current = None
    seen_in_group = set()

    for raw_line in text.splitlines():
        # Strip comments and whitespace.
        line = raw_line.split("#", 1)[0].strip()
        if not line or ":" not in line:
            continue
        field, _, value = line.partition(":")
        field = field.strip().lower()
        value = value.strip()

        if field == "user-agent":
            token = value.lower()
            # Multiple UA lines share one group: reuse current group if the
            # previous meaningful directive was also user-agent.
            if current is not None and "ua" in seen_in_group:
                current.agents.append(token)
            else:
                current = RuleGroup()
                current.agents.append(token)
                robots.groups.append(current)
                seen_in_group.clear()
            seen_in_group.add("ua")
        elif field in ("allow", "disallow"):
            if current is None:
                continue  # rule before any UA: ignore
            if field == "allow" and value == "":
                continue  # empty Allow is meaningless
            current.rules.append((field == "allow", value))
            seen_in_group.add("rule")
        # Unknown fields (crawl-delay, sitemap, ...) are ignored.

    return robots

